#!/usr/bin/env bash

set -euo pipefail

if [[ $# -ne 4 ]]; then
  echo "usage: $0 <version> <tag> <checksums-file> <output-file>" >&2
  exit 2
fi

version="$1"
tag="$2"
checksums_file="$3"
output_file="$4"

if [[ ! "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+-timo\.[0-9]+$ ]]; then
  echo "invalid release version: $version" >&2
  exit 1
fi

if [[ "$tag" != "v$version" ]]; then
  echo "tag $tag does not match version $version" >&2
  exit 1
fi

if [[ ! -f "$checksums_file" ]]; then
  echo "checksums file not found: $checksums_file" >&2
  exit 1
fi

checksum_for() {
  local filename="$1"
  local checksum

  checksum="$(awk -v filename="$filename" '$2 == filename { print $1 }' "$checksums_file")"
  if [[ ! "$checksum" =~ ^[0-9a-f]{64}$ ]]; then
    echo "missing or invalid checksum for $filename" >&2
    exit 1
  fi
  printf '%s' "$checksum"
}

darwin_arm64="glow-timo_${version}_Darwin_arm64.tar.gz"
darwin_amd64="glow-timo_${version}_Darwin_x86_64.tar.gz"
linux_arm64="glow-timo_${version}_Linux_arm64.tar.gz"
linux_amd64="glow-timo_${version}_Linux_x86_64.tar.gz"

darwin_arm64_sha="$(checksum_for "$darwin_arm64")"
darwin_amd64_sha="$(checksum_for "$darwin_amd64")"
linux_arm64_sha="$(checksum_for "$linux_arm64")"
linux_amd64_sha="$(checksum_for "$linux_amd64")"

mkdir -p "$(dirname "$output_file")"

cat >"$output_file" <<EOF
# typed: false
# frozen_string_literal: true

# This file is generated by the glow release workflow. DO NOT EDIT.
class GlowTimo < Formula
  desc "Render Markdown on the CLI with Timo-In's custom features"
  homepage "https://github.com/Timo-In/glow"
  version "$version"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/Timo-In/glow/releases/download/$tag/$darwin_arm64"
      sha256 "$darwin_arm64_sha"
    else
      url "https://github.com/Timo-In/glow/releases/download/$tag/$darwin_amd64"
      sha256 "$darwin_amd64_sha"
    end
  end

  on_linux do
    if Hardware::CPU.arm?
      url "https://github.com/Timo-In/glow/releases/download/$tag/$linux_arm64"
      sha256 "$linux_arm64_sha"
    else
      url "https://github.com/Timo-In/glow/releases/download/$tag/$linux_amd64"
      sha256 "$linux_amd64_sha"
    end
  end

  conflicts_with "glow", because: "both install a glow binary"

  def install
    bin.install "glow"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/glow --version")
  end
end
EOF
